import heapq
from collections import defaultdict, deque

def minPath(grid, k):
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(x, y, k):
        return abs(k - (x + y + 1)) + abs(k - (2 * n - x - y))

    def getNeighbors(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                yield (nx, ny)

